// SPDX-License-Identifier: MIT
// OpenZeppelin Compact Contracts — Standalone Shielded ERC20 Token
// Demonstrates privacy-preserving shielded token operations on Midnight.

pragma language_version >= 0.22.0;

import
  { ShieldedCoinInfo,
    ShieldedSendResult,
    sendImmediateShielded,
    mintShieldedToken,
    shieldedBurnAddress,
    ZswapCoinPublicKey,
    ContractAddress,
    Either,
    left,
    ownPublicKey,
    receiveShielded,
    evolveNonce,
    upgradeFromTransient,
    Counter }
  from CompactStandardLibrary;

import "./modules/utils/Utils" prefix Utils_;

// Public state
export ledger _counter: Counter;
export ledger _nonce: Bytes<32>;
export ledger _totalSupply: Uint<128>;
export ledger _domain: Bytes<32>;
export ledger _name: Opaque<"string">;
export ledger _symbol: Opaque<"string">;
export ledger _decimals: Uint<8>;
export ledger _type: Bytes<32>;
export ledger _isInitialized: Boolean;

constructor() {
  _counter.increment(0);
}

/**
 * Initializes the contract by setting the initial nonce and token metadata.
 */
export circuit initialize(
                 initNonce: Bytes<32>,
                 name_: Opaque<"string">,
                 symbol_: Opaque<"string">,
                 decimals_: Uint<8>,
                 domain_: Bytes<32>
                 ): [] {
  assert(!_isInitialized, "ShieldedToken: already initialized");
  _isInitialized = true;
  _nonce = disclose(initNonce);
  _domain = disclose(domain_);
  _name = disclose(name_);
  _symbol = disclose(symbol_);
  _decimals = disclose(decimals_);
}

export circuit name(): Opaque<"string"> {
  assert(_isInitialized, "ShieldedToken: not initialized");
  return _name;
}

export circuit symbol(): Opaque<"string"> {
  assert(_isInitialized, "ShieldedToken: not initialized");
  return _symbol;
}

export circuit decimals(): Uint<8> {
  assert(_isInitialized, "ShieldedToken: not initialized");
  return _decimals;
}

export circuit tokenType(): Bytes<32> {
  assert(_isInitialized, "ShieldedToken: not initialized");
  return _type;
}

export circuit totalSupply(): Uint<128> {
  assert(_isInitialized, "ShieldedToken: not initialized");
  return _totalSupply;
}

export circuit mint(
  recipient: Either<ZswapCoinPublicKey, ContractAddress>,
  amount: Uint<64>
): ShieldedCoinInfo {
  assert(_isInitialized, "ShieldedToken: not initialized");
  assert(!Utils_isKeyOrAddressZero(recipient), "ShieldedToken: invalid recipient");

  _counter.increment(1);
  const newNonce = evolveNonce(_counter, _nonce);
  _nonce = newNonce;
  const ret = mintShieldedToken(_domain, disclose(amount), _nonce, disclose(recipient));
  if (_type == pad(32, "")) {
    _type = ret.color;
  }
  _totalSupply = _totalSupply + disclose(amount) as Uint<128>;
  return ret;
}

export circuit burn(coin: ShieldedCoinInfo, amount: Uint<128>): ShieldedSendResult {
  assert(_isInitialized, "ShieldedToken: not initialized");
  assert(coin.color == _type, "ShieldedToken: token not created from this contract");
  assert(coin.value >= amount, "ShieldedToken: insufficient token amount to burn");

  receiveShielded(disclose(coin));
  _totalSupply = _totalSupply - disclose(amount);

  const sendRes = sendImmediateShielded(disclose(coin), shieldedBurnAddress(), disclose(amount));
  if (sendRes.change.is_some) {
    const caller = left<ZswapCoinPublicKey, ContractAddress>(ownPublicKey());
    sendImmediateShielded(sendRes.change.value, caller, sendRes.change.value.value);
  }

  return sendRes;
}

// SPDX-License-Identifier: MIT
// OpenZeppelin Compact Contracts — Standalone Ownable Vault
// Demonstrates single-owner access control using the OpenZeppelin Ownable pattern.

pragma language_version >= 0.23;

import CompactStandardLibrary;
import "./modules/access/Ownable" prefix Ownable_;
import "./modules/utils/Identity" prefix Identity_;

export { Identity_UserSecretKey, Identity_AdminPublicKey };
export { Identity_deriveAdminPublicKey };
export { Ownable__owner };

// Vault public state
export ledger vaultBalance: Uint<64>;
export ledger vaultConfigValue: Uint<64>;

// Identity witness providing private 32-byte secret
witness getUserSecret(): Identity_UserSecretKey;

/**
 * Initializes the contract and pins the initial owner to the deployer's
 * derived admin public key.
 */
constructor(initialConfig: Uint<64>) {
  const adminKey = disclose(Identity_deriveAdminPublicKey(getUserSecret()));
  Ownable_initialize(adminKey);
  vaultConfigValue = disclose(initialConfig);
  vaultBalance = 0;
}

// Returns current contract owner
export circuit owner(): Identity_AdminPublicKey {
  return Ownable_owner();
}

// Transfers ownership to a new admin key. Restricted to current owner.
export circuit transferOwnership(newOwner: Identity_AdminPublicKey): [] {
  const caller = disclose(Identity_deriveAdminPublicKey(getUserSecret()));
  Ownable_transferOwnership(caller, newOwner);
}

// Renounces contract ownership. Restricted to current owner.
export circuit renounceOwnership(): [] {
  const caller = disclose(Identity_deriveAdminPublicKey(getUserSecret()));
  Ownable_renounceOwnership(caller);
}

// Updates vault configuration. Guarded: only current owner can execute.
export circuit setVaultConfig(newConfig: Uint<64>): [] {
  const caller = disclose(Identity_deriveAdminPublicKey(getUserSecret()));
  Ownable_assertOnlyOwner(caller);
  vaultConfigValue = disclose(newConfig);
}

// Reads current vault configuration
export circuit getVaultConfig(): Uint<64> {
  return vaultConfigValue;
}

// Deposits funds into the vault balance.
export circuit deposit(amount: Uint<64>): [] {
  vaultBalance = vaultBalance + disclose(amount) as Uint<64>;
}

// Withdraws funds from vault balance. Restricted to current owner.
export circuit withdraw(amount: Uint<64>): [] {
  const caller = disclose(Identity_deriveAdminPublicKey(getUserSecret()));
  Ownable_assertOnlyOwner(caller);
  assert(vaultBalance >= amount, "OwnableVault: insufficient balance");
  vaultBalance = vaultBalance - disclose(amount) as Uint<64>;
}

// SPDX-License-Identifier: MIT
// OpenZeppelin Compact Contracts — Standalone Pausable Token
// Demonstrates emergency circuit-breaker pausing combined with access control.

pragma language_version >= 0.23;

import CompactStandardLibrary;
import "./modules/security/Pausable" prefix Pausable_;
import "./modules/access/Ownable" prefix Ownable_;
import "./modules/utils/Identity" prefix Identity_;

export { Identity_UserSecretKey, Identity_AdminPublicKey };
export { Identity_deriveAdminPublicKey };
export { Pausable__isPaused, Ownable__owner };

// Public state
export ledger balances: Map<Bytes<32>, Uint<64>>;
export ledger totalSupply: Uint<64>;

// Identity witness providing private 32-byte secret
witness getUserSecret(): Identity_UserSecretKey;

/**
 * Initializes the contract, pins the deployer as owner, and starts unpaused.
 */
constructor() {
  const adminKey = disclose(Identity_deriveAdminPublicKey(getUserSecret()));
  Ownable_initialize(adminKey);
  totalSupply = 0;
}

// Check if operations are paused
export circuit isPaused(): Boolean {
  return Pausable_isPaused();
}

// Emergency pause: only owner can halt operations
export circuit pause(): [] {
  const caller = disclose(Identity_deriveAdminPublicKey(getUserSecret()));
  Ownable_assertOnlyOwner(caller);
  Pausable__pause();
}

// Unpause: only owner can resume operations
export circuit unpause(): [] {
  const caller = disclose(Identity_deriveAdminPublicKey(getUserSecret()));
  Ownable_assertOnlyOwner(caller);
  Pausable__unpause();
}

// Mint tokens to an account: restricted to owner
export circuit mint(to: Bytes<32>, amount: Uint<64>): [] {
  const caller = disclose(Identity_deriveAdminPublicKey(getUserSecret()));
  Ownable_assertOnlyOwner(caller);
  assert(to != default<Bytes<32>>, "PausableToken: invalid receiver");

  const currentBal = balanceOf(to);
  balances.insert(disclose(to), disclose(currentBal + amount as Uint<64>));
  totalSupply = disclose(totalSupply + amount as Uint<64>);
}

// Transfer tokens: HALTED if contract is paused
export circuit transfer(fromAccount: Bytes<32>, to: Bytes<32>, amount: Uint<64>): Boolean {
  Pausable_assertNotPaused();
  assert(fromAccount != default<Bytes<32>>, "PausableToken: invalid sender");
  assert(to != default<Bytes<32>>, "PausableToken: invalid receiver");

  const fromBal = balanceOf(fromAccount);
  assert(fromBal >= amount, "PausableToken: insufficient balance");

  balances.insert(disclose(fromAccount), disclose(fromBal - amount as Uint<64>));
  const toBal = balanceOf(to);
  balances.insert(disclose(to), disclose(toBal + amount as Uint<64>));
  return true;
}

// Query account balance
export circuit balanceOf(account: Bytes<32>): Uint<64> {
  if (!balances.member(disclose(account))) {
    return 0;
  }
  return balances.lookup(disclose(account));
}

