// =============================================================================
//  SECURE PATTERN — witness-derived identity
// =============================================================================
//  Each instance holds a single 32-byte secret in private state. Caller
//  identity is derived INSIDE the circuit from that secret via domain-separated
//  `persistentHash` (`deriveUserPublicKey` / `deriveAdminPublicKey`), so a
//  caller can only act as the identity they hold the secret for. `ownPublicKey()`
//  is intentionally NOT used for authorization — it is prover-supplied and
//  bypassable. Every exported mutating circuit computes
//  `const caller = disclose(deriveUserPublicKey(getUserSecret()))` and uses
//  that derived key as both the proven identity and the owner/buyer it stores;
//  ownership gates compare `ownerOf(kittyId)` against that derived caller. The
//  module's identity-parameterized circuits (approve / setApprovalForAll /
//  transferFrom) are never re-exported, only the safe wrappers below.
// =============================================================================

import CompactStandardLibrary;

import "./Nft";

// Re-export identity types and pure derivations so the TypeScript layer can
// compute public keys off-chain (e.g. to look up owners/offers by key).
export { UserSecretKey, UserPublicKey, AdminPublicKey };

export { deriveUserPublicKey, deriveAdminPublicKey };

// Export only the read-only views from the Nft module. The module's
// identity-parameterized mutating circuits (approve / setApprovalForAll /
// transferFrom / mint / burn) are deliberately NOT re-exported — exposing them
// would let a caller pass any `caller` identity and defeat the protection.
// Instead, the safe wrappers below compute the caller from the witness secret.
export { balanceOf, ownerOf, getApproved, isApprovedForAll, tokenExists };

// =====================
// CryptoKitties-specific data structures
// =====================

// Enum representing the gender of a kitty.
export enum Gender {
  Male,
  Female
}

// Struct holding all attributes for a kitty.
export struct Kitty {
  dna: Field, // Unique DNA for the kitty
  gender: Gender, // Gender of the kitty
  owner: UserPublicKey, // Owner's DERIVED public key
  price: Uint<64>, // Sale price (0 if not for sale)
  forSale: Boolean, // Whether the kitty is for sale
  generation: Uint<32> // Generation number (0 for original, increments with breeding)
}

export struct Offer {
  kittyId: Uint<64>,
  buyer: UserPublicKey, // Buyer's DERIVED public key
  price: Uint<64>
}

// Mapping from kitty ID to kitty data.
export ledger kitties: Map<Uint<64>, Kitty>;

// Counter to track the total number of kitties created.
export ledger allKittiesCount: Counter;

// Boolean used to alternate gender assignment for new kitties.
export ledger genderSelector: Boolean;

// Mapping for kitty ID to Account to offer data.
export ledger buyOffers: Map<Uint<64>, Map<UserPublicKey, Offer>>;

// Witness function: each prover supplies their own 32-byte secret from private
// state. The caller's identity is DERIVED from this secret inside the circuit;
// it is never a value the caller can choose arbitrarily.
witness getUserSecret(): UserSecretKey;

// Witness function to retrieve a random number (for DNA generation and breeding).
// WARNING: This is a witness, meaning the value is injected from outside the circuit
// and cannot be fully trusted.
witness createRandomNumber(): Bytes<32>;

// =====================
// Contract Initialization
// =====================

// Contract constructor: initializes the kitty counter.
constructor() {
  allKittiesCount.increment(0);
}

// =====================
// Kitty DNA and Gender Generation
// =====================

// Generates unique DNA for a kitty.
circuit generateDNA(minter: UserPublicKey, kittyId: Uint<64>): Field {
  // In a production implementation, this would use a more secure randomness.
  // Here, we use a hash of the KittyId, minter, contract address, and a witness random number.
  const payload = [kittyId, minter.bytes, kernel.self().bytes, createRandomNumber()];
  return transientHash<[Uint<64>, Bytes<32>, Bytes<32>, Bytes<32>]>(payload);
}

// Determines the gender of a new kitty based on the genderSelector flag.
circuit generateGender(): Gender {
  // Alternate gender for each new kitty.
  if (genderSelector) {
    return Gender.Male;
  } else {
    return Gender.Female;
  }
}

// =====================
// Kitty Lifecycle Operations
// =====================

// Creates a new unique kitty and mints the corresponding NFT.
// The minter/owner is the caller derived from the witness secret.
export circuit createKitty(): [] {
  const sender = disclose(deriveUserPublicKey(getUserSecret()));
  const kittyId = (allKittiesCount.read() + 1) as Uint<64>;
  const kittyDna = generateDNA(sender, kittyId);

  // Ensure the kitty does not already exist.
  assert(!tokenExists(kittyId), "Kitty already exists");

  // Create the new kitty struct.
  const newKitty =
          Kitty { dna: kittyDna,
                  gender: generateGender(),
                  owner: sender,
                  price: 0,
                  forSale: false,
                  generation: 0 };

  // Store the kitty data in the ledger.
  kitties.insert(disclose(kittyId), disclose(newKitty));

  // Mint the NFT using the imported NFT module.
  mint(sender, kittyId);

  // Increment the total kitty counter.
  allKittiesCount.increment(1);
  // Alternate the gender for the next kitty.
  genderSelector = !genderSelector;
}

// Transfers one of YOUR kitties to another account and resets its sale status.
// The caller is derived from the witness secret and is both the proven identity
// and the account the kitty leaves.
export circuit transferKitty(to: UserPublicKey, kittyId: Uint<64>): [] {
  const sender = disclose(deriveUserPublicKey(getUserSecret()));

  // Ensure the kitty exists.
  assert(tokenExists(disclose(kittyId)), "Kitty does not exist");

  // Retrieve the kitty data.
  const kitty = kitties.lookup(disclose(kittyId));

  // Update the kitty's owner and reset sale status.
  const updatedKitty =
          Kitty { dna: kitty.dna,
                  gender: kitty.gender,
                  owner: to,
                  price: 0,
                  forSale: false,
                  generation: kitty.generation };

  kitties.insert(disclose(kittyId), disclose(updatedKitty));

  // Transferring the token resets offers if the kitty was on sale before.
  if (buyOffers.member(disclose(kittyId))) {
    // Note: In a real implementation, currency reimbursement would occur here.
    // The currency transfer would be the bidPrice from the offer.
    // For now, only clear offers.

    // Empty the kitty offers.
    buyOffers.remove(disclose(kittyId));
  }

